// C4 (SPEC-0001): replay traces generated by the Lean model (model/) against the Go
// implementation and compare the observations after every step.
//
// Traces: JSON Lines in the format of SPEC-0001 §4, from PREPARE_DEV_TRACES (a path
// relative to the repository root, or absolute) or model/traces/depth-4.jsonl. The
// files are generated by "lake exe prepare-model gen --depth N" and model/bin/test
// checks that they still match the model.

type traceAction struct {
	Type       string   `json:"type"`
	Question   string   `json:"question"`
	Subjects   []string `json:"subjects"`
	Record     string   `json:"record"`
	Answer     string   `json:"answer"`
	CrashAfter *string  `json:"crash_after"`
}

type traceObserve struct {
	Inflight        bool              `json:"inflight"`
	Pending         []string          `json:"pending"`
	Committed       map[string]string `json:"committed"`
	Closed          []string          `json:"closed"`
	Stale           []string          `json:"stale"`
	PublicDecisions []string          `json:"public_decisions"`
	Result          string            `json:"result"`
}

type traceLine struct {
	Trace   int          `json:"trace"`
	Step    int          `json:"step"`
	Action  traceAction  `json:"action"`
	Observe traceObserve `json:"observe"`
}

func repoRoot() string {
	wd, _ := os.Getwd()
	return filepath.Join(wd, "..", "..")
}

func loadTraces(t *testing.T, file string) ([]int, map[int][]traceLine) {
	f, err := os.Open(file)
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	order := []int{}
	out := map[int][]traceLine{}
	sc := bufio.NewScanner(f)
	sc.Buffer(make([]byte, 1<<20), 1<<24)
	for sc.Scan() {
		line := strings.TrimSpace(sc.Text())
		if line == "" {
			continue
		}
		var tl traceLine
		if err := json.Unmarshal([]byte(line), &tl); err != nil {
			t.Fatal(err)
		}
		if _, ok := out[tl.Trace]; !ok {
			order = append(order, tl.Trace)
		}
		out[tl.Trace] = append(out[tl.Trace], tl)
	}
	if err := sc.Err(); err != nil {
		t.Fatal(err)
	}
	return order, out
}

type idMap struct {
	records     map[string]string // R1 -> REQ-0001
	questions   map[string]string // Q1 -> Q-0001
	answers     map[string]string // A1 -> ANS-0001-1
	answersBack map[string]string
}

func (m *idMap) modelAnswer(impl string) string {
	if a, ok := m.answersBack[impl]; ok {
		return a
	}
	return impl
}

var decIDRE = regexp.MustCompile(`^DEC-0*(\d+)$`)

func modelDecision(impl string) string {
	if m := decIDRE.FindStringSubmatch(impl); m != nil {
		return "D" + m[1]
	}
	return impl
}

func questionOf(m *idMap, modelAnswer string) string {
	impl := m.answers[modelAnswer]
	q := strings.TrimPrefix(impl, "ANS-")
	if i := strings.LastIndex(q, "-"); i >= 0 {
		q = q[:i]
	}
	return "Q-" + q
}

// observeFromDisk reads only persisted files, so it works while the "daemon" is down.
func observeFromDisk(t *testing.T, root string, ids *idMap) traceObserve {
	data, err := os.ReadFile(filepath.Join(root, "prepare", "events.jsonl"))
	if err != nil {
		t.Fatal(err)
	}
	type ev struct {
		Type       string `json:"type"`
		TxID       string `json:"txid"`
		AnswerID   string `json:"answer_id"`
		DecisionID string `json:"decision_id"`
	}
	var intents []ev
	committedTx, abortedTx := map[string]bool{}, map[string]bool{}
	for _, line := range strings.Split(string(data), "\n") {
		if strings.TrimSpace(line) == "" {
			continue
		}
		var e ev
		if err := json.Unmarshal([]byte(line), &e); err != nil {
			t.Fatal(err)
		}
		switch e.Type {
		case "apply.intent":
			intents = append(intents, e)
		case "apply.commit":
			committedTx[e.TxID] = true
		case "apply.abort":
			abortedTx[e.TxID] = true
		}
	}
	obs := traceObserve{Committed: map[string]string{}, Pending: []string{}, Closed: []string{}, Stale: []string{}, PublicDecisions: []string{}}
	for _, i := range intents {
		if !committedTx[i.TxID] && !abortedTx[i.TxID] {
			obs.Inflight = true
		}
		if committedTx[i.TxID] {
			obs.Committed[ids.modelAnswer(i.AnswerID)] = modelDecision(i.DecisionID)
		}
	}
	qfiles, _ := filepath.Glob(filepath.Join(root, "prepare", "questions", "*.json"))
	sort.Strings(qfiles)
	for _, f := range qfiles {
		raw, err := os.ReadFile(f)
		if err != nil {
			t.Fatal(err)
		}
		var q struct {
			Answers []struct {
				AnswerID string          `json:"answer_id"`
				Stale    bool            `json:"stale"`
				Closed   json.RawMessage `json:"closed"`
			} `json:"answers"`
		}
		if err := json.Unmarshal(raw, &q); err != nil {
			t.Fatal(err)
		}
		for _, a := range q.Answers {
			m := ids.modelAnswer(a.AnswerID)
			closed := len(a.Closed) > 0 && string(a.Closed) != "null"
			if closed {
				obs.Closed = append(obs.Closed, m)
			}
			if a.Stale {
				obs.Stale = append(obs.Stale, m)
			}
			if _, ok := obs.Committed[m]; !closed && !ok {
				obs.Pending = append(obs.Pending, m)
			}
		}
	}
	dfiles, _ := filepath.Glob(filepath.Join(root, "prepare", "decisions", "*.md"))
	for _, f := range dfiles {
		raw, err := os.ReadFile(f)
		if err != nil {
			t.Fatal(err)
		}
		fm, _, err := core.ParseMarkdown(string(raw))
		if err != nil {
			t.Fatal(err)
		}
		tx, _ := fm.Str("txid")
		if tx == "" || committedTx[tx] {
			id, _ := fm.Str("id")
			obs.PublicDecisions = append(obs.PublicDecisions, modelDecision(id))
		}
	}
	sort.Strings(obs.Pending)
	sort.Strings(obs.Closed)
	sort.Strings(obs.Stale)
	sort.Strings(obs.PublicDecisions)
	return obs
}

func externalEdit(t *testing.T, root, rel string) {
	abs := filepath.Join(root, rel)
	data, err := os.ReadFile(abs)
	if err != nil {
		t.Fatal(err)
	}
	fm, body, err := core.ParseMarkdown(string(data))
	if err != nil {
		t.Fatal(err)
	}
	body = fmt.Sprintf("%s\n編集 %d %f\n", body, time.Now().UnixNano(), rand.Float64())
	if err := os.WriteFile(abs, []byte(core.SerializeMarkdown(fm, body)), 0o644); err != nil {
		t.Fatal(err)
	}
}

func sortedCopy(s []string) []string {
	out := append([]string{}, s...)
	sort.Strings(out)
	return out
}

func sameStrings(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func sameMap(a, b map[string]string) bool {
	if len(a) != len(b) {
		return false
	}
	for k, v := range a {
		if b[k] != v {
			return false
		}
	}
	return true
}

type traceMismatch struct {
	Step     int          `json:"step"`
	Action   traceAction  `json:"action"`
	Expected traceObserve `json:"expected"`
	Actual   traceObserve `json:"actual"`
}

func replayTrace(t *testing.T, lines []traceLine) *traceMismatch {
	root, err := os.MkdirTemp("", "prepare-dev-conf-")
	if err != nil {
		t.Fatal(err)
	}
	defer os.RemoveAll(root)
	ids := &idMap{records: map[string]string{}, questions: map[string]string{}, answers: map[string]string{}, answersBack: map[string]string{}}
	rt, err := Open(root, Options{})
	if err != nil {
		t.Fatal(err)
	}
	for _, r := range []string{"R1", "R2"} {
		rec, err := rt.Store.CreateRecord("requirement", core.OM("title", r), r+"\n")
		if err != nil {
			t.Fatal(err)
		}
		ids.records[r] = rec.ID
	}
	chosen := "a"
	decision := core.DecisionDraft{Title: "判断", Body: "理由\n", Chosen: &chosen, Alternatives: []string{}}
	up := func() *Runtime {
		if rt == nil {
			t.Fatalf("daemon is down; the model must emit recover first")
		}
		return rt
	}
	for _, line := range lines {
		a := line.Action
		result := "ok"
		var opErr error
		switch a.Type {
		case "create_question":
			subjects := make([]string, len(a.Subjects))
			for i, s := range a.Subjects {
				subjects[i] = ids.records[s]
			}
			q, err := up().Questions.Create(CreateQuestionInput{Kind: "single_choice", Prompt: a.Question, Subjects: subjects, Options: []core.QuestionOption{{Key: "a", Label: "a"}}})
			opErr = err
			if err == nil {
				ids.questions[a.Question] = q.ID
			}
		case "edit":
			externalEdit(t, root, filepath.Join("prepare", "requirements", ids.records[a.Record]+".md"))
		case "save_answer":
			_, ans, err := up().Questions.Answer(ids.questions[a.Question], AnswerInput{Choice: []string{"a"}})
			opErr = err
			if err == nil {
				ids.answers[a.Answer] = ans.AnswerID
				ids.answersBack[ans.AnswerID] = a.Answer
			}
		case "ack":
			_, opErr = up().Questions.Ack(questionOf(ids, a.Answer), ids.answers[a.Answer])
		case "close":
			_, opErr = up().Questions.Close(questionOf(ids, a.Answer), ids.answers[a.Answer], "trace")
		case "apply":
			var hooks *ApplyHooks
			if a.CrashAfter != nil {
				stage := *a.CrashAfter
				hooks = &ApplyHooks{AfterStage: func(s string) error {
					if s == stage {
						return &core.SimulatedCrash{Stage: s}
					}
					return nil
				}}
			}
			r, err := up().Questions.Apply(questionOf(ids, a.Answer), ids.answers[a.Answer], decision, nil, hooks)
			opErr = err
			if err == nil {
				result = r.Status
			}
		case "recover":
			if rt != nil && len(rt.Store.InflightIntents()) == 0 {
				result = "noop"
				break
			}
			rt, err = Open(root, Options{})
			if err != nil {
				t.Fatalf("recover: %v", err)
			}
			switch {
			case len(rt.Recovery.Recovered) == 0:
				result = "noop"
			case rt.Recovery.Recovered[0].Outcome == "forward":
				result = "recovered_forward"
			default:
				result = "recovered_abort"
			}
		default:
			t.Fatalf("unknown action %q", a.Type)
		}
		if opErr != nil {
			var crash *core.SimulatedCrash
			var re *core.RuntimeError
			switch {
			case errors.As(opErr, &crash):
				result = "crashed"
				rt = nil
			case errors.As(opErr, &re):
				switch re.Code {
				case "stale":
					result = "rejected_stale"
				case "closed":
					result = "rejected_closed"
				case "inflight":
					result = "rejected_inflight"
				default:
					result = "error:" + re.Code
				}
			default:
				t.Fatalf("step %d %s: %v", line.Step, a.Type, opErr)
			}
		}
		actual := observeFromDisk(t, root, ids)
		actual.Result = result
		exp := line.Observe
		compareResult := a.Type == "apply" || a.Type == "recover"
		same := actual.Inflight == exp.Inflight &&
			sameStrings(actual.Pending, sortedCopy(exp.Pending)) &&
			sameMap(actual.Committed, exp.Committed) &&
			sameStrings(actual.Closed, sortedCopy(exp.Closed)) &&
			sameStrings(actual.Stale, sortedCopy(exp.Stale)) &&
			sameStrings(actual.PublicDecisions, sortedCopy(exp.PublicDecisions)) &&
			(!compareResult || actual.Result == exp.Result)
		if !same {
			return &traceMismatch{Step: line.Step, Action: a, Expected: exp, Actual: actual}
		}
	}
	return nil
}

func TestModelTraces(t *testing.T) {
	run(t, "[C4] implementation agrees with the Lean model on every generated trace", func(t *testing.T) {
		file := os.Getenv("PREPARE_DEV_TRACES")
		if file == "" {
			file = filepath.Join("model", "traces", "depth-4.jsonl")
		}
		if !filepath.IsAbs(file) {
			file = filepath.Join(repoRoot(), file)
		}
		order, traces := loadTraces(t, file)
		t.Logf("replaying %d traces from %s", len(order), file)
		if len(order) == 0 {
			t.Fatal("no traces")
		}
		type failure struct {
			Trace    int            `json:"trace"`
			Mismatch *traceMismatch `json:"mismatch"`
		}
		var failures []failure
		steps := 0
		for _, idx := range order {
			steps += len(traces[idx])
			if m := replayTrace(t, traces[idx]); m != nil {
				failures = append(failures, failure{Trace: idx, Mismatch: m})
			}
		}
		first := failures
		if len(first) > 5 {
			first = first[:5]
		}
		rel, err := filepath.Rel(repoRoot(), file)
		if err != nil {
			rel = file
		}
		t.Logf("C4: %d traces, %d steps, %d failures (%s)", len(order), steps, len(failures), rel)
		// the gotest plugin adds this to the run's scope.bounds, so the evidence names the
		// traces it replayed
		writeBounds(t, "c4", map[string]any{"c4_traces": len(order), "c4_steps": steps, "c4_failures": len(failures), "c4_trace_file": filepath.ToSlash(rel)})
		if len(failures) > 0 {
			data, _ := json.MarshalIndent(first, "", "  ")
			t.Fatalf("implementation disagrees with the model:\n%s", data)
		}
	})
}

// writeBounds writes a JSON object to the run's bounds directory (PREPARE_DEV_BOUNDS_DIR,
// set by the gotest plugin); outside a verification run it does nothing.
func writeBounds(t *testing.T, name string, v map[string]any) {
	t.Helper()
	dir := os.Getenv("PREPARE_DEV_BOUNDS_DIR")
	if dir == "" {
		return
	}
	data, _ := json.MarshalIndent(v, "", "  ")
	if err := os.WriteFile(filepath.Join(dir, name+".json"), data, 0o644); err != nil {
		t.Fatal(err)
	}
}

// modelDigest is the digest model/bin/test writes to traces/model.sha256 after it has
// checked the traces against the model: sha256 over "<path>\n<sha256 of the file>\n"
// for the model's Lean files, lakefile.toml, lean-toolchain and lake-manifest.json,
// sorted by path, outside .lake.
func modelDigest(t *testing.T, dir string) string {
	t.Helper()
	var files []string
	err := filepath.WalkDir(dir, func(p string, d os.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() && p != dir && strings.HasPrefix(d.Name(), ".") {
			return filepath.SkipDir
		}
		name := d.Name()
		if d.Type().IsRegular() && (strings.HasSuffix(name, ".lean") || name == "lakefile.toml" || name == "lean-toolchain" || name == "lake-manifest.json") {
			rel, _ := filepath.Rel(dir, p)
			files = append(files, filepath.ToSlash(rel))
		}
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
	sort.Strings(files)
	var b strings.Builder
	for _, f := range files {
		data, err := os.ReadFile(filepath.Join(dir, filepath.FromSlash(f)))
		if err != nil {
			t.Fatal(err)
		}
		sum := sha256.Sum256(data)
		b.WriteString(f + "\n" + hex.EncodeToString(sum[:]) + "\n")
	}
	sum := sha256.Sum256([]byte(b.String()))
	return hex.EncodeToString(sum[:])
}

// The traces C4 and C5 replay must be what the current model generates. model/bin/test
// regenerates them, compares, and only then records the model's digest; a model changed
// without that check fails here.
func TestTraceProvenance(t *testing.T) {
	run(t, "[C4][C5] the replayed traces were checked against the current Lean model", func(t *testing.T) {
		model := filepath.Join(repoRoot(), "model")
		recorded, err := os.ReadFile(filepath.Join(model, "traces", "model.sha256"))
		if err != nil {
			t.Fatalf("model/traces/model.sha256 is missing: run model/bin/test (%v)", err)
		}
		current := modelDigest(t, model)
		if strings.TrimSpace(string(recorded)) != current {
			t.Fatalf("the Lean model changed after its traces were checked (recorded %s, now %s): run model/bin/test", strings.TrimSpace(string(recorded)), current)
		}
		writeBounds(t, "model", map[string]any{"model_digest": current})
	})
}
